 1 // `andesim --version` -- collect and print the identity of every bundled
 2 // component. See version.hpp for why the four are versioned by different means.
 3 //
 4 // The build-time half comes from build_stamp.h, regenerated on every build. The
 5 // run-time half is asked of the binaries actually in use: a prebuilt QEMU or
 6 // engine can be older than the source tree it sits in, so only the binary can
 7 // say what it is. Nothing here can fail the command -- a binary that is absent
 8 // or silent leaves its field empty, which renders "unknown".
 9 #include <cstdio>
10 #include <string>
11 #include <string_view>
12 
13 #include "build_stamp.h"
14 #include "engine_registry.hpp"
15 #include "process.hpp"
16 #include "version.hpp"
17 
18 namespace andes_sim {
19 namespace {
20 
21 constexpr int kProbeTimeoutMs = 5000;
22 
23 // Ask one binary for its own version; "" when it cannot be reached, hangs, or
24 // says nothing usable. `parse` lifts the value out of that binary's wording.
25 std::string ask(const std::string& bin,
26                 std::string (*parse)(std::string_view)) {
27   if (bin.empty()) return "";
28   RunResult r = run_process({bin, "--version"}, kProbeTimeoutMs);
29   if (r.spawn_failed || r.timed_out) return "";
30   return parse(r.out);
31 }
32 
33 }  // namespace
34 
35 int cmd_version() {
36   VersionReport rep;
37   rep.release = ANDESIM_RELEASE;
38   rep.andesim = ANDESIM_GIT_ID;
39   rep.abi = ANDESIM_ABI_GIT_ID;
40 
41   rep.qemu_bin = builtin_qemu().bin_path;
42   rep.qemu = ask(rep.qemu_bin, parse_qemu_version);
43 
44   // Every cycle-accurate engine that discovery finds -- the same binaries a run
45   // would use. QEMU has its own line, so the functional engines are skipped.
46   const Discovery disc = discover_engines();
47   for (const EngineDescriptor& e : disc.engines) {
48     if (e.kind != "cycle-accurate") continue;
49     rep.engines.push_back({e.id, ask(e.bin_path, parse_engine_version)});
50   }
51 
52   std::fputs(format_version_report(rep).c_str(), stdout);
53   return 0;
54 }
55 
56 }  // namespace andes_sim

