  // ---- the rendered report ------------------------------------------------
  //
  // A fully-populated report. Every engine binary comes out of one vsim build,
  // so they normally all report the same commit: say it ONCE, unadorned.
  {
    VersionReport r;
    r.release = "v0.1.0";
    r.andesim = "llamacpp/437da16";
    r.abi = "main/9ecc0cc";
    r.qemu = "10.2.3";
    r.engines = {{"vsim:ax46mpv_fpga_l3", "87a0baa"}};
    CHECK(format_version_report(r) ==
          "AndeSim   v0.1.0 (llamacpp/437da16)\n"
          "  abi     main/9ecc0cc\n"
          "  qemu    10.2.3\n"
          "  engine  87a0baa\n");
  }

  // ... however many engines agree on it.
  {
    VersionReport r;
    r.engines = {{"vsim:a", "87a0baa"}, {"vsim:b", "87a0baa"},
                 {"vsim:c", "87a0baa"}};
    CHECK(format_version_report(r) ==
          "AndeSim   unknown (unknown)\n"
          "  abi     unknown\n"
          "  qemu    unknown\n"
          "  engine  87a0baa\n");
  }

  // A MIXED install is the whole reason this report exists, so it stays
  // visible: one line per distinct version, each naming who reports it.
  // Grouped by version, not by engine.
  {
    VersionReport r;
    r.release = "v0.1.0";
    r.andesim = "llamacpp/437da16";
    r.abi = "main/9ecc0cc";
    r.qemu = "10.2.3";
    r.engines = {{"vsim:a", "87a0baa"}, {"vsim:b", "9b01c20"},
                 {"vsim:c", "87a0baa"}};
    CHECK(format_version_report(r) ==
          "AndeSim   v0.1.0 (llamacpp/437da16)\n"
          "  abi     main/9ecc0cc\n"
          "  qemu    10.2.3\n"
          "  engine  87a0baa (vsim:a, vsim:c)\n"
          "  engine  9b01c20 (vsim:b)\n");
  }

  // Unreachable components are still reported, clearly marked unknown: no
  // engine discovered at all, and a QEMU binary that did not answer (its
  // path is shown, so the reader knows what was asked).
  {
    VersionReport r;
    r.release = "v0.1.0";
    r.andesim = "llamacpp/437da16";
    r.abi = "main/9ecc0cc";
    r.qemu_bin = "/opt/qemu/qemu-system-riscv64";
    CHECK(format_version_report(r) ==
          "AndeSim   v0.1.0 (llamacpp/437da16)\n"
          "  abi     main/9ecc0cc\n"
          "  qemu    unknown (/opt/qemu/qemu-system-riscv64)\n"
          "  engine  unknown (no engine binary found)\n");
  }

  // An engine binary that was found but did not answer --version is named:
  // "a binary is there and it is mute" is not "there is no binary".
  {
    VersionReport r;
    r.engines = {{"vsim:mute", ""}};
    CHECK(format_version_report(r) ==
          "AndeSim   unknown (unknown)\n"
          "  abi     unknown\n"
          "  qemu    unknown\n"
          "  engine  unknown (vsim:mute)\n");
  }
  {
    VersionReport r;
    r.engines = {{"vsim:a", ""}, {"vsim:b", ""}};
    CHECK(format_version_report(r) ==
          "AndeSim   unknown (unknown)\n"
          "  abi     unknown\n"
          "  qemu    unknown\n"
          "  engine  unknown (vsim:a, vsim:b)\n");
  }

  // One answered, one did not: two groups, both named.
  {
    VersionReport r;
    r.engines = {{"vsim:a", "87a0baa"}, {"vsim:b", ""}};
    CHECK(format_version_report(r) ==
          "AndeSim   unknown (unknown)\n"
          "  abi     unknown\n"
          "  qemu    unknown\n"
          "  engine  87a0baa (vsim:a)\n"

