// Engines bucketed by the version they reported, in first-appearance order so
// the output is stable. Engines that did not answer share the empty bucket.
std::vector<VersionGroup> group_by_version(
    const std::vector<EngineVersion>& engines) {
  std::vector<VersionGroup> groups;
  for (const EngineVersion& e : engines) {
    auto same = [&](const VersionGroup& g) { return g.version == e.version; };
    auto it = std::find_if(groups.begin(), groups.end(), same);
    if (it == groups.end())
      groups.push_back({e.version, {e.id}});
    else
      it->ids.push_back(e.id);
  }
  return groups;
}

