// usual case is a single shared commit: report it once, unadorned -- repeating
// it per engine is noise. Only when the install is not uniform (different
// versions, or a binary that did not answer) does the reader need to know
// which binary said what, and then the lines are grouped by version, not by
// engine.
void engine_rows(std::string& out, const std::vector<EngineVersion>& engines) {
  const std::vector<VersionGroup> groups = group_by_version(engines);
