// With ram_base support (U10d/U10e) fast+linux addresses the contiguous
// high view: DRAM alias (2 GiB) + DRAM_EXT (14 GiB) from 0x8_00000000, so
// the ceiling is 16 GiB (QEMU AE350 refuses more). Hybrid keeps its own
// separate 2 GiB cap in cmd_run.
{
  // within the window -> no error
  CHECK(fast_linux_mem_error("2G").empty());
  CHECK(fast_linux_mem_error("1G").empty());
  CHECK(fast_linux_mem_error("2097148K").empty());
  CHECK(fast_linux_mem_error("3G").empty());
  CHECK(fast_linux_mem_error("6G").empty());
  CHECK(fast_linux_mem_error("16G").empty());
  // empty spec: the 1G default is applied later, nothing to reject
  CHECK(fast_linux_mem_error("").empty());
  // past the window -> a message naming the flag, the cap and the runtime
  const std::string e = fast_linux_mem_error("17G");
  CHECK(!e.empty());
  CHECK(e.find("--mem-size") != std::string::npos);
  CHECK(e.find("16G") != std::string::npos);
  CHECK(e.find("linux") != std::string::npos);
  // malformed specs are qemu_m_args's business, not this check's
  CHECK(fast_linux_mem_error("8X").empty());
}

